import { cookies, headers } from 'next/headers'

export default async function ThemeDisplay() {
  const cookieStore = await cookies()
  const headersList = await headers()

  // Get theme cookie, default to 'light' if not found
  const themeCookie = cookieStore.get('theme')
  const theme = themeCookie?.value || 'light'

  // Get Accept-Language header
  const acceptLanguage = headersList.get('accept-language') || 'Not specified'

  return (
    <div style={{ padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
      <h2>User Preferences</h2>
      <div style={{ marginTop: '10px' }}>
        <strong>Theme:</strong> {theme}
      </div>
      <div style={{ marginTop: '10px' }}>
        <strong>Preferred Language:</strong> {acceptLanguage}
      </div>
    </div>
  )
}

